from typing import List

def array_operations(arr: List[int], x: int, y: int) -> int:
    extra = x - y

    def feasible(m: int) -> bool:
        need = 0
        for a in arr:
            rem = a - m * y
            if rem > 0:
                need += (rem + extra - 1) // extra
                if need > m:
                    return False
        return True

    lo, hi = 0, (max(arr) + y - 1) // y if max(arr) > 0 else 0
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


if __name__ == "__main__":
    n = int(input())
    arr = list(map(int, input().split()))
    x, y = map(int, input().split())
    print(array_operations(arr, x, y))
